"""Протокол покрытия выбранных открытых каталогов, без персональных примеров."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
cards=json.loads((R/'research/codes-v4/cards.json').read_text())
observed=json.loads((R/'research/codes-v4/observed_urls.json').read_text())
extras={
'https://kb.1cmr.ru/pages/viewpage.action?pageId=10322017':('Каталог ошибок 1C-MR','Прочитано оглавление; исследованы разделы РЭМД, МСЭ, статистической карты и указатель ЭЛН.'),
'https://kb.1cmr.ru/pages/viewpage.action?pageId=36834949':('Коды РЭМД в 1C-MR','Пройден перечень отдельных статей; отсутствие доступа к двум ответам и один технический отказ перечислены отдельно.'),
'https://kb.1cmr.ru/pages/viewpage.action?pageId=46008940':('Коды проверки направления МСЭ','Прочитано оглавление и все 23 конечных ссылки правил У1, У3, Core, Extra и общих ограничений. Вложения и закрытые задачи не использовались.'),
'https://kb.1cmr.ru/pages/viewpage.action?pageId=46009243':('Прочие коды РЭМД для МСЭ','Прочитан указатель; проверены статьи RESTRICT_NEW_VERSION, XML_VALIDATION_ERROR и SIGNATURE_VERIFICATION_ERROR. Повторная ссылка о сертификате покрыта отдельным разбором.'),
'https://kb.1cmr.ru/pages/viewpage.action?pageId=46008200':('Указатель ошибок ЭЛН','Прочитан указатель двух ситуаций без кодов; новые карточки кодов не извлечены.'),
'https://docs.medflex.ru/egisz/api/remd/documents/':('Ответы регистрации документов МедФлекс','Прочитаны примеры кодов ответа и описание статусов. Ссылка на федеральный справочник проверена; технические примеры не перенесены врачу.'),
'https://solutions.1c.ru/catalog/region/proxy':('Интеграция 1С Регион с ЕГИСЗ','Прочитан раздел проверок и связи с Больницей/Поликлиникой; открыта ссылка на исходники валидатора.'),
}
blocked={
'https://kb.1cmr.ru/pages/viewpage.action?pageId=46009234':('RATE_LIMIT','Требуется вход; доступен только заголовок каталога.'),
'https://kb.1cmr.ru/pages/viewpage.action?pageId=24293149':('Несовпадение сведений сертификата','Требуется вход. Другие публичные разборы того же кода прочитаны отдельно.'),
'https://kb.1cmr.ru/pages/viewpage.action?pageId=46006531':('PATIENT_CREATION_ERROR','Технический отказ проверки robots.txt; содержимое не получено. Причина проверена по независимому открытому источнику оператора.'),
'https://kb.1cmr.ru/pages/viewpage.action?pageId=46008240':('Коды ИП ООГУЗ','Основная страница недоступна инструменту. Поисковый фрагмент публичного PDF содержит DOC_TYPE_NOT_VALID; в основную базу не добавлен.'),
'https://nsi.rosminzdrav.ru/dictionaries/1.2.643.5.1.13.13.99.2.305/passport/latest':('Федеральный справочник ошибок РЭМД','Тайм-аут и затем отказ инструмента. Федеральный перечень целиком не прочитан.'),
'https://github.com/1CMedicine/semd_validator':('Исходники проверки СЭМД по ссылке 1С','404. Реестр числовых статусов непосредственно у разработчика не получен.'),
'https://spbmiac.ru/wp-content/uploads/2022/06/%D0%9E%D0%B1%D1%83%D1%87%D0%B5%D0%BD%D0%B8%D0%B5-%D0%BE%D1%88%D0%B8%D0%B1%D0%BA%D0%B8-%D0%A0%D0%AD%D0%9C%D0%94-v.7-2.pdf':('Материалы СПб МИАЦ об ошибках РЭМД','502. Есть поисковый фрагмент, PDF не прочитан; SIGNER_ORG_MISMATCH остаётся кандидатом, не готовым ответом.'),
}
allurls=sorted(set(observed)|set(extras)|set(blocked)|{u for c in cards for u in c['source_urls']})
register=[]
for u in allurls:
    linked=[c for c in cards if u in c['source_urls']]
    title='; '.join(c['title'] for c in linked) or 'Дополнительная статья каталога 1C-MR'
    coverage='Прочитан текст статьи, сопоставлены условия и действия. Персональные примеры и содержимое изображений не перенесены.'
    if u in extras:title,coverage=extras[u]
    access='Прочитан доступный текст'
    if u in blocked:title,coverage=blocked[u];access='Содержательный текст не получен'
    if u.endswith('pageId=65110384'):
        coverage='Прочитан ответ NO_DOCUMENT_KIND_ON_DATE. Совет о паспортных реквизитах не согласуется с расшифровкой кода у оператора. Врачебная инструкция из этого ответа не заимствована.'
    if u.endswith('pageId=46006682'):
        coverage='Прочитан перечень ошибок формирования рецепта ЛЛО. Номера строк модулей и коды льгот не являются кодами ошибок; в расширение кодов не включены.'
    register.append(dict(url=u,title=title,type='Первичная документация реализации / оператора' if '1cmr' in u or 'medflex' in u else 'Дополнительный первичный источник',product='1C-MR' if '1cmr' in u else 'МедФлекс / РЭМД' if 'medflex' in u else 'Указан в источнике',access=access,coverage=coverage,trust='Не подтверждает применимость в Иванове. Расшифровка, гипотеза и исправление учитываются раздельно.',checked_on='2026-10-30'))
(R/'research/codes-v4/source_audit.json').write_text(json.dumps(register,ensure_ascii=False,indent=2)+'\n')
lines=['# Проверка корпуса кодов','',f'Проверено URL в расширении: {len(register)}. Включены указатели, доступные разборы и неудачные обращения. Это не число сайтов и не число подтверждённых решений.','', '## Границы покрытия','', 'Полностью пройден текстовый перечень выбранного раздела РЭМД 1C-MR и 23 конечные страницы правил МСЭ. Полностью прочитан содержательный раздел справочника МедФлекс. Это не полный список всех ошибок всех версий 1С и региональных систем.','', '## Не переносить как универсальное исправление','', '- NO_DOCUMENT_KIND_ON_DATE: совет 1C-MR о паспорте противоречит смыслу кода в справочнике оператора; в карточке оставлена проверка вида СЭМД и даты.', '- Автоматическая обработка 1C-MR от 04.12.2025 описывает условия и исключение для МСЭ редакции 6. Она не гарантирована в неизвестной больнице.', '- SIGNATURE_DUPLICATION: удаление подписей из исходных инструкций заменено согласованным исправлением через поддержку.', '- Одинаковые У1-20, У1-21, У1-27 и Core03-1 разнесены по уточняющим полям; номер правила не определяет единственную причину.', '- VALIDATION_ERROR и ValidationError сохранены как разные написания: их тождество не доказано.', '- 201/202 — отсутствие схемы проверки, а не HTTP-успех; 601/602/603 — успешная проверка в описанной реализации и не входят в счётчик ошибок.', '', '## Реестр обращений','']
for s in register:lines += [f'### {s["title"]}',f'- URL: {s["url"]}',f'- Доступ: {s["access"]}',f'- Изучено: {s["coverage"]}','']
(R/'research/codes-v4/coverage.md').write_text('\n'.join(lines)+'\n')
print('Зафиксировано источников расширения:',len(register))
